#!/usr/bin/env python3
import os
import time
from pathlib import Path

import serial

PORT = "/dev/ttyACM0"
LOG = Path("/tmp/contest-pr6-timer-raw.log")


def stamp(stream, message):
    line = f"\n[HOST {time.strftime('%Y-%m-%d %H:%M:%S')}] {message}\n"
    stream.write(line.encode())
    stream.flush()


def open_port(deadline):
    while time.time() < deadline:
        try:
            if os.path.exists(PORT) and os.access(PORT, os.R_OK | os.W_OK):
                return serial.Serial(PORT, 115200, timeout=0.1)
        except (serial.SerialException, OSError):
            pass
        time.sleep(0.05)
    raise TimeoutError(f"timed out opening {PORT}")


def reconnect(stream, reason):
    stamp(stream, f"serial disconnected ({reason}); wait for re-enumeration")
    return open_port(time.time() + 30)


def collect_resilient(port, stream, seconds):
    deadline = time.time() + seconds
    while time.time() < deadline:
        try:
            data = port.read(4096)
            if data:
                stream.write(data)
                stream.flush()
        except (serial.SerialException, OSError) as exc:
            try:
                port.close()
            except Exception:
                pass
            port = reconnect(stream, type(exc).__name__)
    return port


def send(port, stream, command, wait):
    stamp(stream, f"send: {command}")
    port.write(command.encode() + b"\r\n")
    port.flush()
    return collect_resilient(port, stream, wait)


with LOG.open("wb") as stream:
    port = open_port(time.time() + 15)
    stamp(stream, "toggle RTS reset; capture across every USB re-enumeration")
    port.dtr = False
    port.rts = True
    time.sleep(0.15)
    port.rts = False
    port = collect_resilient(port, stream, 12)

    port = send(port, stream, "uptime", 3)
    port = send(port, stream, 'time "sleep 1"', 4)
    port = send(port, stream, 'time "sleep 10"', 13)
    port = send(port, stream, 'time "usleep 500000"', 4)
    port = send(port, stream, "uptime", 3)
    port = send(port, stream, "reboot", 12)
    port = send(port, stream, "uptime", 3)
    port.close()

